def messenger_icon(key):
    if key == 'telegram':
        return '<svg viewBox="0 0 1000 1000" aria-hidden="true"><circle cx="500" cy="500" r="500" fill="currentColor"/><path d="'+TG_PATH+'" fill="white"/></svg>'
